using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CoastalForestPines {
const string D="Assets/Scenes/Oasis/CoastalTerrain";static CoastalForestPines(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoastalForestPines.request"))return;try{File.Delete("CoastalForestPines.request");}catch(IOException){return;}Run();}
struct Tree{public Vector3 basePoint;public float height;}
static List<Tree> Shape(Mesh m){var w=new List<Vector4>();m.GetUVs(1,w);var p=m.vertices;var groups=new Dictionary<Vector2,List<int>>();for(int i=0;i<p.Length;i++){var key=new Vector2(w[i].y,w[i].z);if(!groups.ContainsKey(key))groups[key]=new List<int>();groups[key].Add(i);}var trees=new List<Tree>();foreach(var g in groups){float bottom=g.Value.Min(i=>p[i].y),top=g.Value.Max(i=>p[i].y);bool done=m.name.Contains("Forest structured");foreach(int i in g.Value)if(!done){p[i]=new Vector3(g.Key.x+(p[i].x-g.Key.x)*.87f,bottom+(p[i].y-bottom)*1.3f,g.Key.y+(p[i].z-g.Key.y)*.87f);}trees.Add(new Tree{basePoint=new Vector3(g.Key.x,bottom,g.Key.y),height=(top-bottom)*(done?1:1.3f)});}m.vertices=p;m.RecalculateBounds();var bounds=m.bounds;bounds.Expand(.6f);m.bounds=bounds;if(!m.name.Contains("Forest structured"))m.name+=" Forest structured";EditorUtility.SetDirty(m);return trees;}
static Mesh Wood(List<Tree> trees){var p=new List<Vector3>();var uv=new List<Vector2>();var ids=new List<int>();Action<Vector3,Vector3,float,float> limb=(a,b,ra,rb)=>{var axis=(b-a).normalized;var right=Vector3.Cross(axis,Mathf.Abs(axis.y)>.9f?Vector3.forward:Vector3.up).normalized;var forward=Vector3.Cross(axis,right);int first=p.Count;for(int ring=0;ring<2;ring++)for(int k=0;k<6;k++){float angle=k*Mathf.PI/3;var offset=(right*Mathf.Cos(angle)+forward*Mathf.Sin(angle))*(ring==0?ra:rb);p.Add((ring==0?a:b)+offset);uv.Add(new Vector2(k/6f,ring));}for(int k=0;k<6;k++){int n=(k+1)%6;ids.AddRange(new[]{first+k,first+6+k,first+n,first+n,first+6+k,first+6+n});}};foreach(var t in trees){float h=t.height;limb(t.basePoint,t.basePoint+Vector3.up*h*.96f,h*.016f,h*.002f);for(int level=0;level<5;level++)for(int j=0;j<3;j++){float y=h*(.32f+level*.115f);float angle=j*Mathf.PI*2/3+level*1.73f+t.basePoint.x*.17f;var a=t.basePoint+Vector3.up*y;float length=h*(.15f-level*.019f);var b=a+new Vector3(Mathf.Cos(angle)*length,h*.035f,Mathf.Sin(angle)*length);limb(a,b,h*.005f,h*.001f);}}var mesh=new Mesh{name="Low poly forest trunks and branches",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(p);mesh.SetUVs(0,uv);mesh.SetTriangles(ids,0);mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;}
static void AddWood(GameObject prefab,Mesh mesh,Material mat){var old=prefab.transform.Find("Forest trunks and branches");GameObject g=old?old.gameObject:new GameObject("Forest trunks and branches");g.transform.SetParent(prefab.transform,false);var f=g.GetComponent<MeshFilter>();if(!f)f=g.AddComponent<MeshFilter>();f.sharedMesh=mesh;var r=g.GetComponent<MeshRenderer>();if(!r)r=g.AddComponent<MeshRenderer>();r.sharedMaterial=mat;var lod=prefab.GetComponent<LODGroup>();var levels=lod.GetLODs();for(int i=0;i<levels.Length;i++)levels[i].renderers=levels[i].renderers.Where(v=>v&&v!=r).Concat(i==0?new[]{r}:new Renderer[0]).ToArray();lod.SetLODs(levels);lod.RecalculateBounds();}
static void Run(){try{var mat=AssetDatabase.LoadAssetAtPath<Material>(D+"/Details/Shared mountain bark.mat");mat.SetColor("_BaseColor",new Color(.26f,.20f,.13f));mat.enableInstancing=true;EditorUtility.SetDirty(mat);var seen=new HashSet<Mesh>();int count=0;foreach(string guid in AssetDatabase.FindAssets("t:Prefab",new[]{D+"/Prefabs"})){string path=AssetDatabase.GUIDToAssetPath(guid);if(!Path.GetFileName(path).StartsWith("Pine_")&&!Path.GetFileName(path).StartsWith("Natural Pine"))continue;var prefab=PrefabUtility.LoadPrefabContents(path);List<Tree> trees=null;foreach(var f in prefab.GetComponentsInChildren<MeshFilter>()){if(f.name=="Forest trunks and branches")continue;var m=f.sharedMesh;if(!m)continue;if(seen.Add(m)){var list=Shape(m);if(f.name=="Detailed")trees=list;}else if(f.name=="Detailed")trees=Shape(m);}if(trees!=null){string meshPath=D+"/Details/Forest Wood "+Path.GetFileNameWithoutExtension(path)+".asset";var mesh=Wood(trees);var existing=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(existing){existing.Clear();existing.indexFormat=mesh.indexFormat;existing.vertices=mesh.vertices;existing.triangles=mesh.triangles;existing.uv=mesh.uv;existing.normals=mesh.normals;existing.RecalculateBounds();UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,meshPath);AddWood(prefab,mesh,mat);count+=trees.Count;}PrefabUtility.SaveAsPrefabAsset(prefab,path);PrefabUtility.UnloadPrefabContents(prefab);}AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Tall-Forest-Pine-Prefabs"});File.WriteAllText("FinalEnvironmentRoadReview/ForestPineReport.txt","SUCCESS tall forest pine mesh assets="+seen.Count+" tree representations="+count+"; slender crowns 30% taller; six-sided physical trunks and tiered branches in near LOD; prefab sector batching retained; foliage wind retained; shrubs unchanged.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/ForestPineReport.txt","FAILED "+e);Debug.LogException(e);}}
}
